$(document).ready(function(){$("#internal-test-submit").click(function(){const i=$("#account-test").val().replaceAll(/\s/g,""),n=i.split(";").filter(n=>n),r=$("#OriginalAccountTest").val(),t=r.split(";").filter(n=>n),u=t.filter(t=>!n.includes(t)),f=n.filter(n=>!t.includes(n));$.ajax({type:"POST",url:"/internalTestAccount/update",data:{addAccounts:f,deletedAccounts:u},dataType:"json",success:function(){$("#successMsg").show();setTimeout(function(){location.reload()},1e3)}})})});